/* Sous-lot 6d-2 : défense NRBC et soutien, dans la rubrique « Contributions des fonctions » (chargé après rens.js).
   Modules nr_* (examen « nr ») et sl_* (examen « sl ») ; tous figurent aussi dans l'examen « fx ». Encarts dans le cycle (FX_ENC). */
const NR_MODS=[
{id:"nr_men",grp:FX_GRP,title:"NRBC : risques et menaces",qtag:"NRBC",
 but:"Connaître les effets que l’ennemi recherche avec des armes NRBC et la nature des dangers nucléaire, chimique, biologique et industriel, pour intégrer la menace NRBC à l’analyse de l’ennemi et du milieu.",
 sections:[
 {h:"Un continuum de risques et de menaces",l:["Le risque et la menace NRBC forment un continuum de plus en plus poreux, du risque naturel jusqu’à l’ennemi symétrique doté de capacités NRBC offensives.","Quels que soient la mission et le théâtre, le risque biologique naturel et le risque industriel doivent toujours être pris en compte."]},
 {h:"Les effets recherchés par l’ennemi",l:["Interdire : empêcher, gêner ou retarder l’activité d’une unité ou l’usage d’un espace pendant un temps donné (par exemple, contaminer une zone avec un agent chimique persistant).","Freiner : ralentir une unité dans une zone (par exemple, un agent non persistant qui impose le port des équipements de protection).","Détruire : rendre une unité définitivement inapte au combat, sauf reconstitution, réorganisation, décontamination ou remplacement (par exemple, une arme nucléaire tactique).","Neutraliser : rendre une unité inefficace pour une durée variable (par exemple, la contaminer avec un agent persistant).","Leurrer : tromper l’adversaire sur sa connaissance de l’environnement NRBC (par exemple, un agent nouveau ou difficile à détecter, qui prolonge le port des protections).","Harceler : créer un climat d’insécurité dans une zone (par exemple, des attaques non persistantes qui cloisonnent la force adverse)."]},
 {h:"Les invariants tactiques",l:["Désorganiser la chaîne de commandement : frappes chimiques à longue portée ou nucléaires tactiques sur les PC, épandage par drone, sabotage d’un site d’intérêt NRBC (effets : détruire, leurrer, harceler).","Désorganiser la chaîne logistique en zone arrière pour isoler l’échelon de tête : attaques biologiques ou chimiques d’ampleur sur les emprises logistiques, ou épandages discrets sur les axes (effets : harceler, neutraliser, leurrer).","Neutraliser tactiquement des unités pour obtenir un rapport de forces favorable."],go:["sl_div"]},
 {h:"La menace nucléaire",l:["Cinq effets : mécanique, thermique et lumino-thermique, rayonnements nucléaires, impulsion électromagnétique, psychologique.","Leur portée et leur durée croissent avec la puissance de l’engin ; leur intensité croît en se rapprochant du point zéro, à la verticale de l’explosion.","Contrairement aux armes chimiques et biologiques, interdites par des traités, l’arme nucléaire est licite. L’emploi du nucléaire tactique ne peut plus être exclu en haute intensité."]},
 {h:"La menace chimique",l:["Danger caractérisé par la diversité des agents et de leurs effets, sa variation avec la météorologie, son caractère insidieux et des mesures de protection contraignantes.","Deux effets principaux : la toxicité (dose en phase liquide, concentration x temps en phase vapeur) et la persistance (durée d’efficacité après dispersion, selon la contamination des surfaces, l’agent et la météorologie).","Non persistant : quelques minutes au sol, sous forme de vapeur ou d’aérosol ; danger gaz, sans contamination ; plutôt délivré par tirs percutants, pour former un nuage au ras du sol. Persistant : de quelques heures à quelques semaines, sous forme liquide ; contamination ; plutôt délivré par épandage ou tirs fusants.","Emplois : neutraliser des unités (non persistant), interdire un terrain (persistant), détruire ou réduire la capacité des unités (l’un ou l’autre).","Vecteurs : obus d’artillerie et de mortier (en principe de calibre 81 mm et plus), roquettes, missiles balistiques tactiques, bombes et réservoirs d’épandage d’avions, drones, moyens divers (grenades, mines, émetteurs de fumées).","Trois formes d’agression : vapeurs, gouttelettes, aérosols. Dès la fin de l’attaque, le chef doit connaître au plus vite l’état de ses forces et l’état du terrain."]},
 {h:"Le risque et la menace biologiques",l:["Cinq familles d’agents : bactéries, rickettsies, virus, toxines, champignons. Une arme biologique associe un agent, un vecteur et un moyen de dispersion.","Pénétration respiratoire, digestive, cutanée, muqueuse ou percutanée ; vecteurs conventionnels (avions, drones, missiles, bombes, roquettes) ou naturels (eau, air, aliments, porteurs humains et animaux).","L’arme biologique est l’arme de désorganisation par excellence : le danger peut durer des heures, des jours, exceptionnellement des années ; la contagion de certains agents rend son emploi moins contrôlable ; l’impact psychologique peut être lourd.","La détection et l’identification immédiates sont aujourd’hui impossibles : on vise le « temps utile », assez tôt pour prendre en charge le personnel exposé et appliquer les contre-mesures médicales.","Veille biologique : le service de santé (veille sanitaire et épidémiologique), l’appui NRBC spécialisé (prélèvements et analyses) et les unités non spécialisées (vigilance : cadavres d’animaux, état de santé des populations…).","Les conflits dégradent l’hygiène et favorisent les maladies endémiques : l’hygiène en campagne préserve la capacité opérationnelle."]},
 {h:"Les risques industriels et la menace terroriste",l:["Les sites industriels peuvent devenir des armes par destination entre les mains de l’ennemi pour réduire les capacités d’une force et contraindre sa manœuvre.","Sites à risque : réacteurs, usines de retraitement, irradiateurs, entrepôts de déchets radioactifs, industries chimiques, raffineries et dépôts d’hydrocarbures, transports de matières dangereuses, installations médicales et laboratoires, stockages de produits chimiques, production de stupéfiants.","Menace terroriste radiologique : bombe sale ou dissémination de matières radioactives (contamination ou irradiation). Menace chimique et biologique : attaque de la population, détournement de moyens industriels, préparation d’attentat ; la plus vraisemblable repose sur les sites industriels."],go:["nr_def"]}],
 vig:["Analyser la menace NRBC ennemie comme une capacité de manœuvre : quel effet, sur quelle cible, à quel moment ?","PC et emprises logistiques sont des cibles privilégiées des frappes NRBC.","Recenser les sites industriels de la zone : ils peuvent devenir des armes par destination.","Un agent persistant contamine et interdit le terrain ; un non persistant neutralise sans contaminer."],
 apply:[{t:"note",x:"Analyse la menace NRBC ennemie et les risques de ta zone : pour chaque menace, l’agent ou le vecteur, l’effet recherché, la cible probable, les indices qui la signaleraient et la parade envisagée."},
  {t:"table",id:"nrmen",l:"Menace et risques NRBC",cols:[{k:"a",l:"Menace ou risque (agent, vecteur, site)"},{k:"e",l:"Effet recherché",o:["Interdire","Freiner","Détruire","Neutraliser","Leurrer","Harceler"]},{k:"c",l:"Cible ou zone probable"},{k:"i",l:"Indices"},{k:"p",l:"Parade envisagée",s:1}]},
  {t:"doc",l:"Menace et risques NRBC"}],
 quiz:[
 {q:"Contaminer une zone avec un agent chimique persistant pour en empêcher l’usage relève de l’effet…",o:["interdire","harceler","leurrer","freiner"],a:0,e:"Interdire : empêcher, gêner ou retarder l’usage d’un espace pendant un temps donné."},
 {q:"Employer un agent nouveau, difficile à identifier, pour prolonger le port des protections adverses relève de l’effet…",o:["leurrer","détruire","interdire","neutraliser"],a:0,e:"Leurrer agit sur la connaissance de l’environnement NRBC."},
 {q:"Lequel est un invariant tactique de l’emploi ennemi des armes NRBC ?",o:["Désorganiser la chaîne de commandement en frappant les PC","Frapper exclusivement la population civile","N’employer que des armes nucléaires","Éviter les zones arrière"],a:0,e:"Autres invariants : désorganiser la logistique en zone arrière, neutraliser tactiquement des unités."},
 {q:"Lequel n’est PAS un effet de l’arme nucléaire ?",o:["L’effet de contagion","L’effet mécanique","L’impulsion électromagnétique","L’effet psychologique"],a:0,e:"S’y ajoutent les effets thermique et lumino-thermique et les rayonnements."},
 {q:"Comment appelle-t-on le point à la verticale d’une explosion nucléaire ?",o:["Le point zéro","Le point initial","Le point de dislocation","Le point d’impact"],a:0,e:"L’intensité des effets croît en s’en rapprochant."},
 {q:"Quelle est la persistance au sol d’un agent chimique non persistant ?",o:["Quelques minutes","Quelques heures","Quelques jours","Quelques semaines"],a:0,e:"Il agit sous forme de vapeur ou d’aérosol, sans contaminer durablement."},
 {q:"Qu’implique un agent chimique persistant ?",o:["Un danger liquide ou aérosol et une contamination","Un danger gaz sans contamination","Aucune mesure de protection","Une action de quelques minutes seulement"],a:0,e:"Il sert surtout à interdire un terrain."},
 {q:"Comment les agents non persistants sont-ils plutôt délivrés ?",o:["Par tirs percutants, pour créer un nuage au ras du sol","Par épandage aérien, pour couvrir une large surface","Par tirs fusants, pour contaminer les sols durablement","Par sabotage, pour contaminer les réseaux d’eau"],a:0,e:"Les persistants sont plutôt délivrés par épandage ou tirs fusants."},
 {q:"Combien de grandes familles d’agents biologiques distingue-t-on ?",o:["5","3","4","7"],a:0,e:"Bactéries, rickettsies, virus, toxines, champignons."},
 {q:"Quel est l’objectif de la détection biologique ?",o:["Le « temps utile » : identifier assez tôt pour limiter l’impact","L’identification immédiate : nommer l’agent dès sa dispersion","La destruction de l’agent : neutraliser le nuage avant l’impact","La preuve juridique : établir l’emploi de l’agent par l’adversaire"],a:0,e:"L’identification immédiate n’est pas possible aujourd’hui."},
 {q:"Qui effectue les prélèvements et analyses d’échantillons pour la veille biologique ?",o:["L’appui NRBC spécialisé","Le service de santé seul","Les unités non spécialisées","La cellule NRBC de la brigade"],a:0,e:"Le service de santé assure la veille sanitaire ; les unités non spécialisées, la vigilance."},
 {q:"Quelle arme est qualifiée d’arme de désorganisation par excellence ?",o:["L’arme biologique","L’arme nucléaire","L’arme chimique","L’arme radiologique"],a:0,e:"L’arme nucléaire est l’arme de destruction massive par excellence."},
 {q:"Selon quelle logique un site industriel peut-il menacer une force ?",o:["Comme arme par destination entre les mains de l’ennemi","Seulement en cas d’accident naturel","Uniquement sur le territoire national","Jamais en haute intensité"],a:0,e:"Le risque industriel doit toujours être pris en compte."},
 {q:"Quelle est la menace terroriste chimique ou biologique la plus vraisemblable ?",o:["L’emploi de sites industriels comme armes par destination","Une arme nucléaire tactique","Un missile balistique","Une attaque par drones armés de bombes sales"],a:0,e:"Lieux de stockage, transports de produits toxiques, laboratoires."}]},
{id:"nr_def",grp:FX_GRP,title:"Défense NRBC : organisation et moyens",qtag:"NRBC",
 but:"Connaître les missions, les principes et l’organisation de la défense NRBC, ainsi que les moyens de l’appui NRBC spécialisé et leurs capacités, pour savoir ce que la brigade peut demander et obtenir.",
 sections:[
 {h:"Mission générale",l:["Les forces doivent pouvoir s’engager et poursuivre leurs missions sans baisse significative de leur capacité opérationnelle, face à des attaques NRBC répétées en haute intensité.","La défense NRBC participe à la prévention des incidents, protège la force après un incident et ramène la situation à un risque acceptable : elle préserve et restaure la capacité opérationnelle et la liberté d’action du commandement.","Trois missions : l’appui aux forces ; le soutien aux populations (territoire national ou nation hôte) ; la contribution à la lutte contre la prolifération et à la contre-prolifération opérationnelle."]},
 {h:"Principes et niveaux de capacités",l:["Quatre principes : complémentarité, continuité, interopérabilité interarmées et interalliés, synergie interministérielle. « La défense NRBC est l’affaire de tous et pas seulement des spécialistes. »","Niveau générique : tout combattant, avec ses moyens de détection, de protection individuelle et collective et de décontamination immédiate et opérationnelle, assure sa survie et les actes de sa fonction en ambiance NRBC.","Niveau intermédiaire : capacité collective des unités et états-majors non spécialisés à poursuivre leurs activités en ambiance NRBC.","Appui NRBC spécialisé : prélèvement, reconnaissance et décontamination approfondie ; il repose sur le 2e régiment de dragons et les unités médicales de décontamination du régiment médical.","Les niveaux générique et intermédiaire forment la défense NRBC interarmes ; elle suit la situation NRBC par les procédures OTAN d’alerte et de compte rendu."]},
 {h:"Organisation dans les unités et les états-majors",l:["Chaque corps de troupe dispose d’un officier et d’un sous-officier qualifiés ; chaque unité élémentaire d’une équipe NRBC aux ordres de l’adjudant d’unité, qui conseille le commandant d’unité.","À partir de la brigade, l’état-major dispose d’une cellule NRBC de spécialistes qui conseille le chef sur la situation et l’emploi des moyens spécialisés (binôme officier et sous-officier au sein de la cellule opérations-2D).","Brigade SCORPION : une équipe permanente du B3 évalue la menace, suit la situation et gère la messagerie NRBC. Si la brigade reçoit une unité NRBC, son PC est renforcé d’un DL NRBC, habituellement colocalisé avec le B3-2D, qui définit l’emploi des moyens reçus.","L’appui spécialisé est employé de façon centralisée, par économie des moyens ; cet emploi centralisé est coordonné par la brigade du génie.","Coordination : en multinational, l’annexe U de défense NRBC et la chaîne interalliée d’alerte et de compte rendu ; en national, avec les cellules renseignement, 3D, logistique, CIMIC et communication opérationnelle."],go:["or_opo"]},
 {h:"La fonction NRBC vue par l’état-major",l:["G1 : appui prévôtal aux prélèvements à valeur de preuve. G2 : besoins en renseignement, facteurs environnementaux NRBC, capacités NRBC ennemies, modes d’action ennemis sous l’angle NRBC.","G3 : connaissance du milieu, ordres, sécurité du déploiement de l’état-major, dimensionnement de la défense NRBC, règles d’engagement en ambiance NRBC, emploi des moyens spécifiques.","G4 : protection des stocks, itinéraires de secours, mouvements en zone contaminée, recomplètement, évacuation des déchets contaminés, gestion des moyens de protection.","G5 : posture NRBC, répartition des unités, plan d’urgence pour les populations. G6 : chaîne d’alerte, échange entre logiciel de prévision NRBC et SIC, protection contre l’impulsion électromagnétique.","G7 : vérification de l’instruction NRBC, retour d’expérience en boucle courte. G9 : moyens de la force au profit de la population (eau, protection collective, conseil médical, affaires publiques)."]},
 {h:"Missions de l’appui NRBC spécialisé",l:["Prévenir la baisse de capacité : conseiller le commandement, expertiser les risques industriels du théâtre, reconnaître les sites d’implantation, participer aux reconnaissances d’itinéraires et à l’appui à la mobilité, préparer les opérations de décontamination.","Gérer les conséquences : expliquer l’événement et ses conséquences, délimiter les zones contaminées, rechercher des itinéraires de contournement, suivre l’évolution de la contamination, identifier le toxique employé (prélèvements à valeur de preuve juridique), reconnaître un site industriel accidenté.","Restaurer la capacité : conseiller sur la décontamination approfondie, l’exécuter, conseiller sur la levée de l’alerte NRBC.","Contributions détaillées : conseiller, surveiller et alerter, reconnaître, détecter, prélever, identifier, contrôler les zones de danger, relever et trier les victimes, décontaminer, réhabiliter un site, désinfecter, sécuriser, enquêter, appuyer les actions médicales."]},
 {h:"Moyens et pions d’emploi",l:["Volume normé : un escadron d’appui NRBC au profit d’une brigade interarmes. Le 2e régiment de dragons, subordonné à la brigade du génie, compte 5 escadrons NRBC identiques : 1 peloton de commandement et de logistique, 1 peloton d’équipes de reconnaissance et d’évaluation (3 équipes), 1 peloton de reconnaissance (2 patrouilles de VAB RECO NRBC), 2 pelotons de décontamination approfondie.","Équipe de reconnaissance et d’évaluation (ERE, 6 personnes) : qualifie et quantifie seule un risque chimique (toxiques industriels, agents de guerre) ou radiologique ; 1 à 2 missions par jour ; un prélèvement en une demi-journée, hors délais de déplacement.","Patrouille de reconnaissance NRBC (17 personnes, 3 VAB RECO NRBC) : environ 8 axes de 20 km par jour en appui à la mobilité, ou 2 sites de 5 à 20 ha par jour après un événement. Évolution prévue : reconnaissances débarquée (SERVAL) et embarquée (GRIFFON) fusionnées en 2 pelotons par escadron.","Peloton de décontamination (34 personnes) : arme les trois chantiers de décontamination approfondie, personnel, véhicules, petits matériels et matériels sensibles.","Peloton mixte d’appui direct : une patrouille de reconnaissance et une patrouille de décontamination avancée, qui donnent à l’unité appuyée tout le spectre de l’appui spécialisé.","Section de décontamination médicale : prise en charge des blessés contaminés, livrés sans armement ni équipement ; 2 h de travail au plus au niveau de protection 4 ; 4 blessés par heure et par chantier, 8 pour une section à 2 groupes."],go:["nr_dct"]},
 {h:"Niveaux de protection",l:["Cinq niveaux, de N0 à N4, harmonisés avec ceux de l’OTAN et fixés en fonction de la menace.","N0 : masque à portée de main, aucune mesure de protection collective. N1 : équipements distribués mais non déconditionnés ; filtres verrouillés sur les engins dotés d’un système NRBC.","N2 : cartouche vissée sur le masque, tenue revêtue capuche ouverte ; véhicules fermés ou bâchés. N3 : surbottes revêtues en plus. N4 : gants revêtus ; filtration et pressurisation des engins dotés.","Si la lettre M suit le niveau (par exemple N2M), le masque doit être porté et la capuche fermée. Le détail figure dans l’outil « Normes et délais »."]}],
 vig:["La défense NRBC est l’affaire de tous : l’appui spécialisé ne remplace pas la défense NRBC interarmes.","L’appui spécialisé est rare : il est employé de façon centralisée.","Le DL NRBC reçu avec une unité spécialisée définit son emploi : l’intégrer au B3-2D.","Prévoir l’appui NRBC dès la planification des reconnaissances d’itinéraires et de sites."],
 apply:[{t:"note",x:"Recense les moyens NRBC dont tu disposes ou que tu demandes : pour chacun, la mission, la subordination, l’unité appuyée et la période."},
  {t:"table",id:"nrmoy",l:"Emploi des moyens NRBC",cols:[{k:"u",l:"Moyen",o:["ERE","Patrouille de reconnaissance NRBC","Peloton de décontamination","Peloton mixte d’appui direct","Section de décontamination médicale","Escadron d’appui NRBC"]},{k:"m",l:"Mission",o:["Reconnaître","Surveiller, alerter","Détecter","Prélever","Identifier","Décontaminer","Conseiller"]},{k:"s",l:"Subordination",o:["Organique","TACOM","TACON","OPCON","Appui direct","Appui général"]},{k:"b",l:"Au profit de"},{k:"h",l:"Période",s:1}]},
  {t:"doc",l:"Emploi des moyens NRBC"}],
 quiz:[
 {q:"Lequel n’est PAS une mission de la défense NRBC ?",o:["La destruction des capacités NRBC ennemies","L’appui aux forces","Le soutien aux populations","La contribution à la lutte contre la prolifération"],a:0,e:"Trois missions : appui aux forces, soutien aux populations, lutte contre la prolifération et contre-prolifération."},
 {q:"Quel principe résume la formule « l’affaire de tous et pas seulement des spécialistes » ?",o:["La complémentarité","La continuité","L’interopérabilité","La synergie interministérielle"],a:0,e:"Trois niveaux complémentaires : générique, intermédiaire, spécialisé."},
 {q:"Qu’assure la défense NRBC « générique » ?",o:["La survie de chaque combattant et les actes de sa fonction en ambiance NRBC","La décontamination approfondie des personnels et des matériels de l’unité","Les prélèvements à valeur de preuve sur les sites d’emploi d’une arme NRBC","La reconnaissance embarquée des itinéraires et des zones contaminées"],a:0,e:"Avec des moyens de détection, de protection et de décontamination immédiate et opérationnelle."},
 {q:"Qu’appelle-t-on la défense NRBC interarmes ?",o:["La conjonction des niveaux générique et intermédiaire","La conjonction des niveaux intermédiaire et spécialisé","L’appui NRBC spécialisé mis à la disposition des GTIA","L’ensemble des escadrons NRBC du 2e régiment de dragons"],a:0,e:"Elle garantit la poursuite des opérations en ambiance NRBC."},
 {q:"Sur quelles unités repose l’appui NRBC spécialisé ?",o:["Le 2e régiment de dragons et les unités médicales de décontamination du régiment médical","Le régiment de cavalerie de la brigade et les équipes NRBC de chaque unité élémentaire","Le régiment du génie de la brigade et les sections de décontamination de la BSD","Le 19e régiment du génie et les postes de décontamination du service de santé"],a:0,e:"Il est employé de façon centralisée."},
 {q:"Qui coordonne l’emploi centralisé de l’appui NRBC spécialisé ?",o:["La brigade du génie","La brigade interarmes","Le régiment médical","La brigade logistique"],a:0,e:"Le 2e RD est subordonné à la brigade du génie."},
 {q:"Quel est le volume normé de l’appui NRBC au profit d’une brigade interarmes ?",o:["Un escadron","Un peloton","Une patrouille","Un régiment"],a:0,e:"Cinq escadrons NRBC identiques au 2e RD."},
 {q:"Dans une brigade SCORPION, qui gère la messagerie NRBC ?",o:["L’équipe permanente qualifiée NRBC du B3","La cellule renseignement NRBC du B2","Le DL de l’escadron NRBC au PC","Le bureau des systèmes d’information B6"],a:0,e:"Elle évalue aussi la menace et suit la situation."},
 {q:"Avec qui le DL NRBC est-il habituellement colocalisé au PC de la brigade ?",o:["Le B3-2D","Le B2","Le B4","La cellule feux"],a:0,e:"Il définit l’emploi des moyens spécialisés reçus."},
 {q:"De combien de personnes se compose une ERE ?",o:["6","4","10","17"],a:0,e:"Elle mène 1 à 2 missions par jour, remise en condition comprise."},
 {q:"Combien d’axes une patrouille de VAB RECO NRBC reconnaît-elle environ par jour ?",o:["8 axes de 20 km","2 axes de 20 km","20 axes de 8 km","4 axes de 50 km"],a:0,e:"Ou 2 sites de 5 à 20 ha après un événement NRBC."},
 {q:"Combien de chantiers un peloton de décontamination peut-il armer ?",o:["3 : personnel, véhicules, petits matériels et matériels sensibles","2 : personnel d’une part, véhicules et matériels de l’autre","4 : personnel, blessés, véhicules et matériels sensibles","1 seul, polyvalent, traitant successivement tous les flux"],a:0,e:"Le chantier blessés est armé par le régiment médical."},
 {q:"Que réunit le peloton mixte d’appui direct NRBC ?",o:["Une patrouille de reconnaissance et une patrouille de décontamination avancée","Deux ERE","Deux pelotons de décontamination","Une patrouille de reconnaissance et une section médicale"],a:0,e:"Il offre tout le spectre de l’appui spécialisé à l’unité appuyée."},
 {q:"Combien de blessés une section de décontamination médicale à 2 groupes traite-t-elle par heure ?",o:["8","4","15","30"],a:0,e:"4 par chantier ; 2 h de travail au plus au niveau de protection 4."},
 {q:"Quel bureau évalue les capacités NRBC ennemies ?",o:["Le G2","Le G3","Le G4","Le G5"],a:0,e:"Il définit aussi les modes d’action ennemis sous l’angle NRBC."},
 {q:"Que signifie la lettre M ajoutée à un niveau de protection NRBC (par exemple N2M) ?",o:["Le masque est porté et la capuche fermée","Le masque est emporté en position « combat »","La protection collective est mise en œuvre","Les gants sont revêtus en plus de la tenue"],a:0,e:"Sans la lettre M, la tenue revêtue (à partir de N2) garde la capuche ouverte."},
 {q:"À partir de quel niveau de protection la tenue NRBC est-elle revêtue ?",o:["N2","N1","N3","N4"],a:0,e:"Capuche ouverte. En N2, les surbottes restent dans le sac de combat et les gants dans le sac de transport."},
 {q:"À quel niveau de protection les gants sont-ils revêtus ?",o:["N4","N2","N3","N1"],a:0,e:"En N4, les engins dotés d’un système NRBC passent en filtration et pressurisation ; les autres sont bâchés."},
 {q:"En N2, que fait-on de la cartouche filtrante ?",o:["On la visse sur le masque, bouchon en place","On la garde scellée dans le sac de transport","On la visse sur le masque, sans bouchon","On la regroupe au niveau du SGTIA"],a:0,e:"En N0 et N1, elle reste non déconditionnée, dans son emballage scellé."}]},
{id:"nr_dct",grp:FX_GRP,title:"La manœuvre de décontamination",qtag:"NRBC",
 but:"Savoir planifier et commander une décontamination approfondie au niveau de la brigade : niveaux, responsabilités, site de décontamination élargi, soutien et délais.",
 sections:[
 {h:"Buts et impératifs",l:["Décontaminer, c’est préserver la liberté d’action du chef en restaurant la capacité opérationnelle des unités contaminées.","Décontaminer dès que possible ; d’abord ce qui est nécessaire à la mission (selon le temps, l’étendue et la persistance de l’agent, la protection individuelle, le terrain et les moyens) ; au plus près du lieu de contamination, en tenant compte de la vulnérabilité du site aux tirs directs et aériens ; selon les priorités tactiques et techniques fixées.","Persistance variable : de quelques heures à quelques semaines pour les agents chimiques, longue pour les aérosols biologiques, selon la période radioactive pour les radionucléides.","Les équipements en matières absorbantes (bois, tissu, certains plastiques) ne sont pas décontaminables : leur remplacement se planifie avant le réengagement des unités traitées."]},
 {h:"Les quatre niveaux de décontamination",l:["Immédiate (générique) : sans ordre, par le combattant, dès la fin des retombées, pour limiter les effets physiologiques et assurer au moins la survie.","Opérationnelle (interarmes) : sur ordre du chef de l’élément, limitée aux interfaces homme-machine (poignées, marchepieds…), pour réduire le transfert de contamination.","Approfondie (appui spécialisé) : permet de lever tout ou partie des mesures de protection ; elle impose de retirer les unités de leur zone d’engagement, hors de combat pour une durée assez longue.","Certifiée : avant le rapatriement des matériels ; elle dépasse généralement les capacités de la force et demande un soutien externe."]},
 {h:"Responsabilités",l:["Le commandement tactique des opérations de décontamination est au minimum du niveau brigade. La brigade dirige la manœuvre depuis son PC, avec ses spécialistes NRBC et le DL de l’unité d’appui NRBC.","Le plan de décontamination figure dans l’OPO (paragraphes et annexe NRBC) pour les mesures préparatoires ; un FRAGO le déclenche, avec le cadre espace-temps de l’unité d’appui NRBC et des autres unités engagées.","Le commandant du GTIA pilote, dans la zone duquel se trouve le site, cadence et régule les mouvements des unités à décontaminer et en assure la sécurité.","L’unité d’appui NRBC commande le site, de l’accueil en zone d’attente jusqu’à la sortie vers la zone de regroupement ; comme le génie sur un site de franchissement, elle planifie les renforcements nécessaires. Le chef du site commande aussi les unités logistiques détachées.","La zone du site, fixée par le PC de la brigade avec le DL NRBC, est généralement contiguë à celle de l’élément logistique de la brigade. La division peut coordonner directement les unités NRBC pour limiter l’impact sur la manœuvre des brigades."],go:["or_opo","sl_div"]},
 {h:"Le site de décontamination élargi (SIDEC)",l:["Survivabilité : camouflage, dispersion, protection, sûreté. Face aux drones, un site à forte empreinte au sol doit être discret et mobile.","Organisation : itinéraire d’accès (plan de circulation) ; point initial ; zone d’accueil et d’attente, en zone sale ; site de décontamination ; zone de regroupement et de remise en condition, en zone propre, où l’unité se rééquipe en matériels non décontaminables ; point de dislocation ; itinéraire de sortie.","Chantier de décontamination des blessés, armé par le régiment médical : place pour le centre de reconditionnement du personnel et l’unité médicale dans la même zone, emplacement des véhicules sanitaires, itinéraire d’évacuation et zone de poser, ravitaillement en eau.","Une cellule restauration et soins, à environ 50 m au-delà de la tente de déshabillage, en zone propre, stabilise le blessé avant son évacuation ; un poste de secours renforce systématiquement le module NRBC de niveau escadron."]},
 {h:"L’appui NRBC de la brigade SCORPION",l:["La décontamination approfondie s’impose après la contamination d’au moins un SGTIA. La brigade peut détacher à ses GTIA des patrouilles de reconnaissance et de décontamination avancée.","Articulation possible d’un escadron d’appui NRBC reçu de la division : un peloton qui décontamine 1 SGTIA par demi-journée (rythme indicatif, selon l’agent et l’unité) ; un peloton à 2 patrouilles détachables dans les GTIA, chacune décontaminant 1 groupe de combat en 1 h ; 2 pelotons de reconnaissance à 2 patrouilles ; 1 DL au PC de la brigade. Appellations de ces deux pelotons : valeur à confirmer.","La brigade conserve ses unités d’appui général, en particulier le peloton de décontamination d’ensemble : la décontamination approfondie est une opération de niveau 3, à cause des appuis qu’elle exige.","Selon la situation, un PC dédié au site permet au PC de la brigade de continuer à commander sa manœuvre."]},
 {h:"Soutien et renforcements du site",l:["L’escadron NRBC ne peut pas se soutenir seul. La brigade fournit (par le groupement du génie s’il en a les moyens, sinon par celui de la division) : la gestion des flux entrants et sortants, l’eau, le rééquipement des unités, la prise en charge des blessés contaminés, l’évacuation des déchets et effluents.","Les itinéraires empruntés par les unités contaminées sont pollués : on ne peut plus les emprunter sans risque de transfert.","Renforts types : un peloton de circulation, un moyen de terrassement, un engin d’appui à la traficabilité, au moins une section de défense rapprochée fournie en principe par l’unité pilote, une couverture sol-air, des citernes ou bacs souples, un soutien du combattant (morgue et tenues de rechange), un soutien santé et un élément pour les déchets.","Eau : environ 200 m³ pour un GTIA, dont si possible 50 m³ d’eau destinée à la consommation humaine pour le personnel ; le centre de reconditionnement du personnel consomme environ 1 500 L par heure.","Rééquipement : stock à l’élément logistique de la brigade, tenues de rechange aux TC1 et à l’élément logistique des GTIA, réserve de théâtre ; délai de 6 à 24 h.","Après l’emploi d’agents R, B ou C, le chef peut décider une restriction de mouvement ou adapter le niveau de protection ; le niveau suivi de la lettre M impose le port du masque, capuche fermée."],go:["sl_sdc"]},
 {h:"Délais NRBC",l:["24 h au maximum entre la contamination d’une unité et la fin de sa décontamination (étanchéité limitée de la tenue) ; en haute intensité, tenir compte aussi du temps de la manœuvre, de la météo et de l’emplacement des plots de décontamination.","Une unité contaminée et protégée (équipements de protection, véhicules en surpression) peut poursuivre sa mission, avec une vitesse « x2 de jour, x4 de nuit » selon la norme. Le chef cherche à la désengager au plus tôt, si possible en fin d’action.","Un peloton NRBC décontamine 1 section en 1 h de jour (2 h de nuit), 3 à 6 sections en 24 h ; un SGTIA de 40 véhicules ou un escadron de chars en 4 à 8 h.","Installation d’un site : 1 h de jour, 2 h de nuit, hors déplacement et reconnaissance, tous les moyens s’installant en même temps.","Ces délais sont appelés à évoluer avec les retours d’expérience récents. Voir aussi la fiche « Normes et délais »."],go:["normes"]}],
 vig:["La décontamination approfondie met l’unité hors de combat : la planifier dans le temps de la manœuvre, si possible en fin d’action.","24 h au plus entre contamination et fin de décontamination.","Pas de site sans renforts : circulation, génie, protection, sol-air, eau, santé, rééquipement, déchets.","Plan de décontamination dans l’OPO, déclenchement par FRAGO."],
 apply:[{t:"note",x:"Prépare le plan de décontamination de ta brigade : implante les éléments du site et désigne pour chacun le responsable ; recense ensuite les renforcements nécessaires et leur fournisseur."},
  {t:"fields",id:"nrdp",l:"Cadre de la décontamination",f:[{k:"pil",l:"Formation pilote et zone du site",a:1},{k:"prio",l:"Priorités de décontamination",a:1},{k:"dec",l:"Déclenchement (FRAGO, critères, délais)",a:1}]},
  {t:"table",id:"nrsite",l:"Site de décontamination élargi",cols:[{k:"e",l:"Élément",o:["Itinéraire d’accès","Point initial","Zone d’accueil et d’attente","Site de décontamination","Chantier blessés","Zone de regroupement et de remise en condition","Point de dislocation","Itinéraire de sortie"]},{k:"l",l:"Localisation"},{k:"r",l:"Responsable"},{k:"o",l:"Observations",s:1}]},
  {t:"table",id:"nrren",l:"Renforcements du site",cols:[{k:"b",l:"Besoin",o:["Circulation","Terrassement","Traficabilité","Défense rapprochée","Défense sol-air","Eau","Rééquipement","Santé","Déchets"]},{k:"u",l:"Unité fournie"},{k:"p",l:"Fournisseur"},{k:"h",l:"Horaires",s:1}]},
  {t:"doc",l:"Plan de décontamination"}],
 quiz:[
 {q:"Quel est le but de la décontamination ?",o:["Préserver la liberté d’action du chef en restaurant la capacité des unités contaminées","Rapatrier les matériels contaminés vers l’arrière pour les rendre à la logistique","Prouver l’emploi d’une arme chimique en recueillant des prélèvements sur les unités","Protéger la population civile en dépolluant les zones touchées par les retombées"],a:0,e:"On décontamine d’abord ce qui est nécessaire à la mission."},
 {q:"Combien de niveaux de décontamination distingue-t-on ?",o:["4","2","3","5"],a:0,e:"Immédiate, opérationnelle, approfondie, certifiée."},
 {q:"La décontamination immédiate est réalisée…",o:["sans ordre, par le combattant, dès la fin des retombées","sur ordre du chef de l’élément, à la fin de la mission","par l’appui NRBC spécialisé, dès la levée de l’alerte","par l’équipe NRBC de l’unité, sur un chantier dédié"],a:0,e:"Elle vise d’abord la survie du combattant."},
 {q:"Sur quoi porte la décontamination opérationnelle ?",o:["Les interfaces homme-machine","Tout le véhicule","Le terrain","Les matériels rapatriés"],a:0,e:"Poignées, marchepieds… pour limiter le transfert de contamination."},
 {q:"Qu’impose la décontamination approfondie ?",o:["Le retrait des unités de leur zone d’engagement","La poursuite du combat sur place","L’emploi d’un laboratoire extérieur","L’intervention des seules unités non spécialisées"],a:0,e:"Les unités sont hors de combat pour une durée assez longue."},
 {q:"À quel niveau minimal se situe le commandement tactique des opérations de décontamination ?",o:["La brigade","Le GTIA","La division","Le SGTIA"],a:0,e:"La brigade dirige la manœuvre depuis son PC."},
 {q:"Où le plan de décontamination trouve-t-il sa traduction ?",o:["Dans l’OPO (paragraphes et annexe NRBC), puis dans un FRAGO au déclenchement","Dans l’annexe logistique seule, puis dans un ordre de mouvement au déclenchement","Dans un message d’alerte NRBC, diffusé par le B3 dès la détection de l’attaque","Dans le plan de renseignement, puis dans un ordre préparatoire au déclenchement"],a:0,e:"Le FRAGO fixe le cadre espace-temps de chaque unité."},
 {q:"Qui cadence et régule les mouvements des unités à décontaminer ?",o:["Le commandant du GTIA pilote","Le chef du site de décontamination","Le B4 de la brigade","Le DL NRBC"],a:0,e:"Il assure aussi la sécurité des mouvements."},
 {q:"Qui commande le site de décontamination élargi ?",o:["L’unité d’appui NRBC","Le GTIA pilote","L’élément logistique de la brigade","Le régiment médical"],a:0,e:"De l’accueil en zone d’attente jusqu’à la sortie vers la zone de regroupement."},
 {q:"Où l’unité se rééquipe-t-elle en matériels non décontaminables ?",o:["Dans la zone de regroupement et de remise en condition","Dans la zone d’accueil et d’attente, avant le chantier","Au point de dislocation, en sortie de chantier","Au point initial, dès l’arrivée sur le site"],a:0,e:"Cette zone est en zone propre, à proximité immédiate du site."},
 {q:"Pourquoi les itinéraires empruntés par les unités contaminées posent-ils problème ?",o:["Ils sont pollués : risque de transfert de contamination","Ils sont détruits : risque d’embouteillage des unités","Ils sont saturés : risque de retard de la logistique","Ils sont exposés : risque d’attaque par l’artillerie"],a:0,e:"La gestion des flux entrants et sortants est un soutien dû par la brigade."},
 {q:"Combien d’eau faut-il environ pour décontaminer un GTIA ?",o:["200 m³","20 m³","50 m³","1 000 m³"],a:0,e:"Dont si possible 50 m³ d’eau destinée à la consommation humaine pour le personnel."},
 {q:"Délai maximal entre la contamination d’une unité et la fin de sa décontamination ?",o:["24 h","12 h","48 h","72 h"],a:0,e:"À cause de l’étanchéité limitée de la tenue de protection."},
 {q:"Combien de temps faut-il pour installer un site de décontamination de jour ?",o:["1 h","30 min","4 h","12 h"],a:0,e:"2 h de nuit, hors déplacement et reconnaissance."},
 {q:"Quel délai de rééquipement après décontamination faut-il prévoir ?",o:["6 à 24 h","1 à 2 h","2 à 3 jours","Une semaine"],a:0,e:"Le temps de préparer la ressource et de la livrer."},
 {q:"Pourquoi la brigade conserve-t-elle le peloton de décontamination d’ensemble ?",o:["La décontamination approfondie est une opération de niveau 3, par les appuis qu’elle exige","La décontamination approfondie est une opération de niveau 4, réalisée au profit des GTIA","Le peloton ne peut pas être détaché, car il appartient organiquement au régiment médical","Le peloton sert d’abord à la reconnaissance NRBC des itinéraires empruntés par la brigade"],a:0,e:"Les patrouilles peuvent, elles, être détachées dans les GTIA."}]}
];
const SL_MODS=[
{id:"sl_gen",grp:FX_GRP,title:"Soutien : généralités et niveau opératif",qtag:"LOG",
 but:"Connaître la fonction soutien, ses sous-fonctions et l’organisation du soutien du théâtre jusqu’aux trains de combat, pour situer la brigade dans la chaîne logistique.",
 sections:[
 {h:"La fonction soutien",l:["Combinaison et ordonnancement des activités qui permettent aux forces de vivre, d’agir, de s’entraîner, de combattre et de durer, du déploiement au désengagement.","Deux fonctions opérationnelles et 12 sous-fonctions. Soutien administratif militaire : soutien administratif, juridique, financier. Soutien logistique : médical, de l’homme, maintenance, pétrolier, acheminement, munitions, stationnement, prévention et maîtrise des risques en opération, condition du personnel en opération.","Les six premières sous-fonctions du soutien logistique (médical, homme, maintenance, pétrolier, acheminement, munitions) conditionnent tout engagement et sont toujours mises en œuvre.","Le soutien s’exerce en continu aux niveaux stratégique, opératif et tactique ; sauf accord particulier, il reste national. L’armée de Terre dépend de l’interarmées, de moins en moins à mesure que l’on se rapproche du front."]},
 {h:"Le niveau opératif",l:["Dès la planification, l’état-major des armées désigne une armée « contributeur principal au soutien » (CPS), qui fournit l’essentiel des capacités logistiques et propose un adjoint soutien interarmées (ASIA).","L’ASIA, auprès du commandant de la force, organise et conduit le soutien au niveau opératif ; il coordonne tous les soutiens, assume généralement le contrôle administratif national et décline les directives administratives et logistiques en ordre administratif et logistique.","Le groupement de soutien interarmées de théâtre (GSIAT, ou JLSG en multinational) regroupe les unités de soutien : entrée de théâtre (réception, stationnement, mouvement, intégration), gestion des stocks, opérations logistiques lourdes (maintenance, médicales), renforcement de la division, soutien d’un camp de prisonniers et de centres d’accueil.","Capacités multimodales : le 1er régiment du Train parachutiste (mise à terre par voie aérienne, ravitaillement par air, transit aérien, commandement d’un point de débarquement aérien) et le 519e régiment du Train (points d’embarquement et de débarquement maritimes, transit portuaire, régulation des flux vers le GSIAT)."]},
 {h:"Le niveau tactique",l:["Pour une division, la brigade de soutien divisionnaire (BSD) arme l’échelon logistique et soutient sans intermédiaire les TC2 des groupements. Elle génère des structures temporaires : BSD avancée (pour sa bascule), détachements avancés de soutien, plots logistiques.","Le groupement tactique logistique (GTLOG) soutient une force du volume d’une BIA en action autonome, ou une opération de faible ampleur jusqu’à 5 000 hommes ; il peut générer au moins un sous-groupement logistique.","Chaque groupement tactique dispose de trains de combat : TC1 dans le sillage des unités élémentaires, TC2 dans le sillage du PC aux ordres du commandant de l’unité de commandement et de logistique, TC3 pour les moyens ne concourant pas directement à l’action.","Le niveau des stocks au GSIAT doit permettre de faire face à une rupture temporaire des flux stratégiques ; des postes de soutien des convois peuvent jalonner les élongations."],go:["sl_div","sl_bsd"]}],
 vig:["Le soutien reste national, sauf accord particulier.","Six sous-fonctions logistiques conditionnent tout engagement.","La BIA n’a pas d’échelon logistique propre : la BSD soutient directement les TC2."],
 apply:[{t:"note",x:"Situe ta brigade dans la chaîne de soutien : qui la soutient (BSD, GTLOG, structure temporaire), où se trouvent les TC2 de ses groupements et quelles sous-fonctions sont critiques pour la mission."},
  {t:"fields",id:"slch",l:"Chaîne de soutien de la brigade",f:[{k:"sup",l:"Échelon de soutien (BSD, GTLOG, DAS, plot)",a:1},{k:"tc",l:"Emplacement des TC2 et des TC3",a:1},{k:"crit",l:"Sous-fonctions critiques pour la mission",a:1}]},
  {t:"doc",l:"Chaîne de soutien de la brigade"}],
 quiz:[
 {q:"Combien de sous-fonctions compte la fonction soutien ?",o:["12","6","9","15"],a:0,e:"3 pour le soutien administratif militaire, 9 pour le soutien logistique."},
 {q:"Laquelle relève du soutien administratif militaire ?",o:["Le soutien juridique","Le soutien pétrolier","L’acheminement","Le soutien au stationnement"],a:0,e:"Avec le soutien administratif et le soutien financier."},
 {q:"Laquelle ne fait PAS partie des six sous-fonctions logistiques qui conditionnent tout engagement ?",o:["Le soutien au stationnement","Le soutien médical","Le soutien munitions","L’acheminement"],a:0,e:"Les six : médical, homme, maintenance, pétrolier, acheminement, munitions."},
 {q:"Sauf accord particulier, le soutien logistique est…",o:["national","interallié","assuré par la nation hôte","assuré par l’OTAN"],a:0,e:"Chaque nation soutient ses forces."},
 {q:"Qui organise et conduit le soutien au niveau opératif ?",o:["L’adjoint soutien interarmées (ASIA)","Le commandant de la BSD","Le B4 de la brigade","Le chef du GTLOG"],a:0,e:"Il est désigné sur proposition de l’armée contributeur principal au soutien."},
 {q:"Comment s’appelle la grande unité qui regroupe les unités de soutien au niveau opératif ?",o:["Le groupement de soutien interarmées de théâtre (GSIAT)","La brigade de soutien divisionnaire de théâtre (BSDT)","Le groupement tactique logistique interarmes (GTLIA)","La brigade logistique de corps d’armée (BLCA)"],a:0,e:"JLSG en multinational."},
 {q:"Quel régiment commande un point de débarquement aérien et met à terre la force par voie aérienne ?",o:["Le 1er régiment du Train parachutiste","Le 519e régiment du Train","Le 14e RISLP","Le régiment médical"],a:0,e:"Le 519e RT arme les points d’embarquement et de débarquement maritimes."},
 {q:"Qui soutient sans intermédiaire les TC2 des groupements d’une division ?",o:["La BSD","Le GSIAT","La brigade interarmes","Le GTLOG"],a:0,e:"La BIA n’a pas d’échelon logistique permanent."},
 {q:"Jusqu’à quel volume un GTLOG soutient-il une opération de faible ampleur ?",o:["5 000 hommes","1 000 hommes","10 000 hommes","20 000 hommes"],a:0,e:"Il soutient une force du volume d’une BIA."},
 {q:"Aux ordres de qui se trouvent les TC2 ?",o:["Du commandant de l’unité de commandement et de logistique","Des commandants d’unité élémentaire, chacun pour la sienne","Du commissaire du groupement, adjoint du chef de corps","Du B4 de la brigade, par l’intermédiaire du chef S4"],a:0,e:"Les TC1 sont aux ordres des commandants d’unité."}]},
{id:"sl_div",grp:FX_GRP,title:"Le système logistique divisionnaire",qtag:"LOG",
 but:"Connaître les principes, les responsabilités et les modes d’action de la logistique divisionnaire, et le rôle du B4 de la brigade, pour intégrer le volet logistique à la manœuvre.",
 sections:[
 {h:"Les principes",l:["Unicité de la manœuvre : il n’y a pas de manœuvre logistique distincte de la manœuvre tactique, mais une manœuvre unique avec un volet logistique, intégré dès la conception ; des phases d’effort logistique encadrent toute phase d’effort tactique.","Efficience : garantir d’abord la liberté d’action du chef ; bon usage des moyens comptés pour répondre au juste besoin et constituer des réserves ; structures temporaires dimensionnées au besoin.","Continuité dans l’espace et le temps : stocks, flux et sûreté des unités de soutien ; toute rupture remet en cause la capacité opérationnelle.","Les systèmes d’information logistiques sont employés a minima en opération : dans la division, à la BSD seulement."],go:["p2e2"]},
 {h:"Élongations",l:["Les TC2 des groupements de 1er échelon se déploient en général à moins de 30 km de la ligne avant des forces amies ; la BSD à moins de 150 km de cette ligne, ou à moins de 120 km des TC2.","Au-delà, la division peut basculer la BSD, déployer des structures temporaires, renforcer les TC2 ou accepter une baisse de la performance du soutien."]},
 {h:"Responsabilités",l:["La division conçoit, planifie et conduit le volet logistique et établit la synthèse logistique (effectifs, disponibilité des matériels majeurs, ressources). Son pôle logistique regroupe les bureaux G1, G4, G8 et soutien santé.","La BSD met en œuvre les opérations logistiques conçues par la division.","La BIA n’a pas d’échelon logistique permanent. Son B4 participe à la conception de la manœuvre et vérifie que la brigade a les moyens de sa mission ; rédige les paragraphes et annexes logistiques des ordres ; suit la situation logistique et contribue à la capacité opérationnelle de la brigade ; veille à la cohérence du dispositif logistique ; évalue les besoins et donne un avis sur les demandes exceptionnelles.","Le groupement tactique exécute les procédures décidées par la division ; son S4 planifie, suit, anticipe et traite les demandes exceptionnelles."],go:["or_opo"]},
 {h:"Les trains de combat",l:["TC1 : en arrière du PC de l’unité élémentaire, à 5 à 10 km de la ligne des contacts (1 à 5 km pour un GTIA à dominante mêlée) ; logistique d’urgence (évacuation, munitions).","TC2 : généralement à 20 à 30 km des TC1, dans une zone attribuée par la brigade, dans le sillage du PC ; îlots ravitaillement, maintenance, santé et groupe de défense NRBC ; renforçable ponctuellement par la BSD.","TC3 : entités administratives et moyens qui gêneraient la manœuvre, aux ordres du commissaire du groupement, généralement implantés à la BSD."]},
 {h:"Les modes d’action logistique",l:["En planification, la division conçoit des plans de soutien : niveau des stocks, organisation des flux, prélèvements et renforcements entre échelons, génération de structures temporaires. En conduite, elle adapte le dispositif par des ordres et directives logistiques.","Flux poussés : initiés par le fournisseur (BSD), confirmés par le destinataire ; risque de stocks à terre en cas de sous-consommation, recomplètement exceptionnel plus lent en cas de surconsommation.","Flux tirés : initiés par le bénéficiaire, selon ses besoins et dans la limite des allocations ; stricte suffisance, prévision des consommations et stock de sécurité.","Livraison : le fournisseur transporte la ressource jusqu’aux unités. Distribution : les TC2 viennent la chercher à la BSD avec leurs vecteurs."]},
 {h:"La sûreté du soutien",l:["Dans la zone arrière, la division assure la sûreté éloignée de la BSD ; dans la zone des brigades, celles-ci assurent la sûreté éloignée, rapprochée, voire immédiate, des structures temporaires.","Chaque grande unité responsable d’une zone assure la sûreté des itinéraires logistiques qui la traversent ; un réseau convoi divisionnaire est nécessaire.","Convois plus petits, plus mobiles et plus simples à commander ; dispersion, dissimulation et protection des emprises, notamment des PC.","Les éléments de soutien nationaux des unités alliées intégrées à la division se déploient au sein de la BSD, sous son contrôle tactique."],go:["nr_men"]}],
 vig:["Une seule manœuvre, avec un volet logistique : effort logistique avant et après chaque effort tactique.","Le B4 rédige les paragraphes et annexes logistiques et vérifie que la brigade a les moyens de sa mission.","Au-delà de 120 km entre BSD et TC2, il faut une solution : bascule, structure temporaire ou renforcement.","La brigade protège les structures logistiques temporaires déployées dans sa zone."],
 apply:[{t:"note",x:"Rédige le concept de soutien de ta manœuvre, phase par phase : effort logistique, mode de flux et de ravitaillement, structure de soutien, sûreté. Vérifie les élongations TC2 – BSD."},
  {t:"table",id:"slcs",l:"Concept de soutien",cols:[{k:"ph",l:"Phase"},{k:"e",l:"Effort logistique",o:["Ravitaillement","Maintenance","Santé","Soutien du combattant"]},{k:"f",l:"Flux",o:["Flux poussés","Flux tirés"]},{k:"r",l:"Ravitaillement",o:["Livraison","Distribution"]},{k:"st",l:"Structure",o:["TC2","DAS","Plot logistique","BSD avancée"]},{k:"o",l:"Élongations et sûreté",s:1}]},
  {t:"doc",l:"Concept de soutien"}],
 quiz:[
 {q:"Que signifie le principe d’unicité de la manœuvre ?",o:["Une manœuvre unique comprenant un volet logistique","Une manœuvre logistique conduite par la BSD seule","Un chef logistique distinct du chef tactique","Une logistique planifiée après la manœuvre"],a:0,e:"Le COMDIV est seul responsable."},
 {q:"Qu’encadre une phase d’effort tactique dans la planification divisionnaire ?",o:["Des phases d’effort logistique en amont et en aval","Des phases de repos des unités en amont et en aval","Une bascule obligatoire de la BSD en amont de l’effort","Des phases de décontamination en amont et en aval"],a:0,e:"C’est la marque de l’intégration du volet logistique."},
 {q:"Où sont déployés les systèmes d’information logistiques dans la division ?",o:["À la BSD seulement","À tous les niveaux","Aux TC2","Au PC de la brigade"],a:0,e:"Ils ne doivent ni limiter la liberté d’action ni alourdir les SIC."},
 {q:"À quelle distance de la ligne avant des forces amies se déploient en général les TC2 de 1er échelon ?",o:["Moins de 30 km","Moins de 10 km","Moins de 60 km","Moins de 150 km"],a:0,e:"La BSD, à moins de 150 km de cette ligne ou 120 km des TC2."},
 {q:"Qui rédige les paragraphes et annexes logistiques des ordres de la brigade ?",o:["Le B4","Le B3","La BSD","Le S4 des groupements"],a:0,e:"La BIA n’a pas d’échelon logistique permanent."},
 {q:"À quelle distance de la ligne des contacts se trouvent en général les TC1 ?",o:["5 à 10 km (1 à 5 km pour un GTIA à dominante mêlée)","20 à 30 km (10 à 15 km pour un GTIA à dominante mêlée)","1 à 2 km (moins de 1 km pour un GTIA à dominante mêlée)","30 à 50 km (20 km pour un GTIA à dominante appui)"],a:0,e:"Ils assurent une logistique d’urgence."},
 {q:"Qui attribue la zone des TC2 ?",o:["La brigade, sur demande","La division","La BSD","Le TC3"],a:0,e:"Les TC2 restent dans le sillage du PC du groupement."},
 {q:"Où le TC3 est-il généralement implanté ?",o:["À la BSD","Au TC2","Au PC de la brigade","Au GSIAT"],a:0,e:"Il est commandé par le commissaire du groupement."},
 {q:"Qui initie les flux tirés ?",o:["Le bénéficiaire de la ressource","Le fournisseur","La division seule","Le GSIAT"],a:0,e:"Ils répondent à la notion de stricte suffisance."},
 {q:"Quel risque présentent les flux poussés en cas de sous-consommation ?",o:["Des stocks à terre qui alourdissent les détenteurs","Une rupture de ravitaillement des unités de l’avant","Un surcoût de transport aérien depuis la métropole","Un arrêt des convois faute de vecteurs disponibles"],a:0,e:"En cas de surconsommation, le recomplètement exceptionnel prend du temps."},
 {q:"En distribution, qui transporte la ressource de la BSD aux unités ?",o:["Les TC2, avec leurs propres vecteurs","La BSD, avec ses propres vecteurs","Le GSIAT, par des convois directs","Les TC1, avec les vecteurs des UE"],a:0,e:"En livraison, c’est le fournisseur qui transporte."},
 {q:"Qui assure la sûreté des structures logistiques temporaires dans la zone des brigades ?",o:["Les BIA","La division","La BSD","Le GSIAT"],a:0,e:"Sûreté éloignée, rapprochée, voire immédiate, selon le contexte."}]},
{id:"sl_bsd",grp:FX_GRP,title:"La brigade de soutien divisionnaire",qtag:"LOG",
 but:"Connaître l’organisation, le déploiement et les structures temporaires de la BSD, pour savoir quel soutien la brigade peut en attendre et dans quels délais.",
 sections:[
 {h:"Missions du PC de la BSD",l:["État-major de niveau 3, il appuie le PC de la division dans la planification (interlocuteur unique, avec les DL des zones fonctionnelles) et dans la synthèse logistique des unités de la division.","Il assure le fonctionnement du soutien : OPO de la BSD, FRAGO logistiques quotidiens (« FRAGO BSD J+1 ») et à l’événement, gestion de l’espace et de la sûreté de la zone, conduite des flux internes et externes.","Il prépare et conduit les adaptations du dispositif selon les plans de soutien de la division : BSD avancée, structures temporaires, renforcement des TC2, adaptation des flux et des stocks."]},
 {h:"Organisation et déploiement",l:["Le PC de la BSD a l’OPCON de groupements qui arment des zones fonctionnelles : 2 zones ravitaillement-transport, 1 zone maintenance, 1 zone santé, 1 zone soutien du combattant ; plus une zone commandement, des capacités SIC et de protection, éventuellement un escadron de circulation et d’escorte.","Environ 6 000 combattants et 1 500 matériels majeurs ; des ressources pouvant dépasser 1 500 équivalents 20 pieds.","Déploiement dans la zone arrière de la division, sur environ 500 à 600 km², à 120 km au plus des TC2 (moins de 4 h de route) : réseau routier maillé avec accès à 2 pénétrantes au moins, raccordement possible à l’eau et à l’électricité, plateformes multimodales, défense passive facilitée.","Au plus près de la zone des brigades en offensive, au plus loin en défensive. Stabilité minimale théorique : 120 h (5 jours), pour les opérations lourdes de santé et de maintenance."]},
 {h:"Stocks et bascule",l:["Par convention, 4 jours de combat à la BSD et 3 aux groupements tactiques : 7 jours d’autonomie pour la division.","À l’ordre de bascule, une BSD à 4 jours de combat met en moyenne 96 h pour basculer l’essentiel de ses capacités sur 60 à 90 km (ordres de grandeur).","Le préavis (WARNO) accélère la préparation ; le FRAGO de bascule déclenche les reconnaissances et le départ du 1er échelon, qui arme la BSD avancée, autonome 48 h. Le PC se scinde en deux structures miroirs.","Les mouvements de bascule durent environ 48 à 72 h en continu : la division identifie au moins 2 couloirs logistiques sécurisés."],go:["normes"]},
 {h:"Compatibilité des modes d’action",l:["Les capacités comptées de la BSD rendent ses modes d’action souvent exclusifs : optimise les moyens et prends en compte leurs délais de mise en œuvre avant de concevoir un nouveau plan de soutien.","La livraison limitée reste compatible avec la bascule et avec tous les déploiements de DAS et de plots LOG.","La bascule exclut le déploiement d’un 2e DAS, celui d’un 2e plot LOG par zone fonctionnelle et la livraison étendue ; le déploiement d’un DAS ou d’un plot LOG par zone reste possible sous conditions.","Un 2e DAS exclut la bascule et les plots LOG. Le tableau complet figure dans l’outil « Normes et délais »."]},
 {h:"Les structures logistiques temporaires",l:["Détachement avancé de soutien (DAS) : unité multifonctionnelle de niveau 4 qui soutient au plus près, environ 48 h, un volume de niveau brigade pour un temps particulier de sa manœuvre (combat en zone urbaine, élongation BSD – TC2 supérieure à 120 km), éventuellement 2 BIA à la fois.","La BSD peut déployer 2 DAS simultanés dans la zone des brigades, sur une zone pouvant atteindre 100 km² ; le DAS est mis sous TACON, voire TACOM, de la BIA soutenue ; son PC est armé en priorité par la zone ravitaillement-transport à laquelle la brigade est rattachée.","Plot logistique : soutien temporaire dans une sous-fonction dominante (santé, soutien du combattant, maintenance, ravitaillement), en général de niveau 5, pour environ 48 h, sous TACON ou TACOM du groupement soutenu ; 2 plots par zone fonctionnelle ; mise en place en moins de 12 h.","La force soutenue assure la sûreté rapprochée du plot, voire immédiate. Les capacités de la BSD étant comptées, ses modes d’action s’excluent souvent : en tenir compte avant de concevoir un nouveau plan de soutien."],go:["p2e5"]},
 {h:"Les zones fonctionnelles",l:["Zones ravitaillement-transport (régiments du Train) : munitions, carburant, équipements d’organisation du terrain ; capacité de transport de 2 jours de combat de haute intensité ; 2 jours de combat de kérosène sur roues ; environ 100 à 150 km² ; arment 2 plots ravitaillement et le noyau d’un DAS.","Zone santé (régiment médical et service de santé) : soutien médical de niveau 2, évacuations, ravitaillement santé ; autonomie de 48 h ; 20 à 30 km² avec si possible une plateforme aérienne ; peut armer un chantier de décontamination des blessés.","Zone maintenance (régiments du Matériel) : réparations trop longues, lourdes ou complexes pour la maintenance de contact, récupération des matériels amis et ennemis ; environ 50 km², de préférence en zone industrielle.","Zone soutien du combattant : vivres, eau, équipements de vie courante et de protection individuelle, affaires mortuaires ; 30 à 40 km², près de la zone santé.","Escadron de circulation et d’escorte : régulation des flux internes de la BSD, fléchage et surveillance des itinéraires internes. Zone commandement : SIC, soutien du quartier général, protection.","Les zones fonctionnelles intègrent sous TACON des TC3, en priorité : ceux des fonctions 2D, 3D et aérocombat en zone ravitaillement-transport ; du combat débarqué en zone santé ; de l’appui au commandement et du renseignement en zone soutien du combattant."]}],
 vig:["7 jours d’autonomie pour la division : 4 jours de combat à la BSD, 3 aux groupements.","Une bascule de BSD prend environ 96 h : l’anticiper dès la planification.","DAS et plots : environ 48 h, sous TACON (voire TACOM) de la force soutenue, qui en assure la sûreté rapprochée.","Les capacités de la BSD sont comptées : ses modes d’action s’excluent souvent."],
 apply:[{t:"note",x:"Si ta manœuvre fait apparaître une élongation ou un temps particulier (zone urbaine, franchissement, effort prolongé), formule la demande de structure temporaire : structure, dominante, subordination, zone, période et sûreté."},
  {t:"table",id:"slst",l:"Structures temporaires demandées",cols:[{k:"s",l:"Structure",o:["DAS","Plot ravitaillement","Plot maintenance","Plot santé","Plot soutien du combattant","Renforcement des TC2"]},{k:"b",l:"Au profit de"},{k:"sub",l:"Subordination",o:["TACON","TACOM"]},{k:"z",l:"Zone"},{k:"h",l:"Période (environ 48 h)"},{k:"su",l:"Sûreté",s:1}]},
  {t:"doc",l:"Structures temporaires demandées"}],
 quiz:[
 {q:"Combien de zones ravitaillement-transport compte la BSD ?",o:["2","1","3","4"],a:0,e:"Plus une zone maintenance, une zone santé et une zone soutien du combattant."},
 {q:"Quelle superficie la BSD occupe-t-elle environ ?",o:["500 à 600 km²","50 à 60 km²","100 à 150 km²","1 000 à 1 500 km²"],a:0,e:"Dans la zone arrière de la division."},
 {q:"À quelle distance maximale des TC2 la BSD se déploie-t-elle ?",o:["120 km (moins de 4 h de route)","60 km (moins de 2 h de route)","200 km (moins de 6 h de route)","30 km (moins de 1 h de route)"],a:0,e:"Compromis entre stabilité, sûreté et élongations."},
 {q:"Quelle est la stabilité minimale théorique de la BSD ?",o:["120 h","48 h","72 h","10 jours"],a:0,e:"Nécessaire aux opérations lourdes de santé et de maintenance."},
 {q:"En offensive, où la BSD se déploie-t-elle ?",o:["Au plus près de la zone des brigades","Au plus loin","Au contact","Sur le territoire national"],a:0,e:"En défensive, au plus loin."},
 {q:"Quelle autonomie logistique la convention donne-t-elle à la division ?",o:["7 jours (4 à la BSD, 3 aux groupements)","4 jours (3 à la BSD, 1 aux groupements)","10 jours (7 à la BSD, 3 aux groupements)","3 jours (2 à la BSD, 1 aux groupements)"],a:0,e:"Exprimée en jours de combat."},
 {q:"Combien de temps une BSD à 4 jours de combat met-elle en moyenne pour basculer l’essentiel de ses capacités ?",o:["96 h","24 h","48 h","7 jours"],a:0,e:"Sur une distance d’environ 60 à 90 km."},
 {q:"Pendant combien de temps la BSD avancée doit-elle soutenir la division en autonomie ?",o:["48 h","12 h","96 h","5 jours"],a:0,e:"Elle est le « harpon » de la BSD pour sa bascule."},
 {q:"Sous quelle subordination un DAS est-il mis au profit d’une BIA ?",o:["TACON, voire TACOM","OPCON","OPCOM","Appui général"],a:0,e:"Pour ne pas changer les processus et laisser la division maîtriser ses capacités."},
 {q:"Dans quel cas typique un DAS soutient-il une brigade ?",o:["Une élongation BSD – TC2 supérieure à 120 km","Une opération de décontamination","Une bascule de la division","Un soutien de théâtre"],a:0,e:"Ou un temps particulier de la manœuvre, comme un combat en zone urbaine."},
 {q:"En combien de temps un plot logistique est-il mis en place ?",o:["Moins de 12 h","Moins de 2 h","Environ 48 h","Environ 96 h"],a:0,e:"Il est ensuite déployé environ 48 h."},
 {q:"Qui assure la sûreté rapprochée d’un plot logistique ?",o:["La force soutenue","La BSD","La division","La zone fonctionnelle qui l’a généré"],a:0,e:"Voire sa sûreté immédiate."},
 {q:"Combien de jours de combat de kérosène la zone ravitaillement-transport détient-elle en permanence sur roues ?",o:["2","1","4","7"],a:0,e:"Ces capacités soutiennent aussi le groupement aéromobile."},
 {q:"Quelle zone fonctionnelle peut armer un chantier de décontamination des blessés ?",o:["La zone santé","La zone maintenance","La zone soutien du combattant","La zone commandement"],a:0,e:"Avec une unité médicale de décontamination des armées."},
 {q:"Quel mode d’action logistique reste pleinement compatible avec une bascule de la BSD ?",o:["Une livraison limitée","Une livraison étendue","Le déploiement d’un 2e DAS","Un 2e plot LOG par zone"],a:0,e:"Un DAS ou un plot LOG par zone fonctionnelle reste possible sous conditions ; un 2e DAS, un 2e plot ou une livraison étendue en sont exclus."},
 {q:"La BSD a déployé deux DAS : que peut-elle encore conduire sans restriction ?",o:["Une livraison limitée","Un plot LOG par zone","Sa bascule","Une livraison étendue"],a:0,e:"La livraison étendue reste possible sous conditions ; la bascule et les plots LOG sont exclus."},
 {q:"Pourquoi le planificateur vérifie-t-il la compatibilité des modes d’action de la BSD ?",o:["Ses capacités comptées les rendent souvent exclusifs","Chacun exige l’accord préalable du niveau opératif","Les zones fonctionnelles agissent l’une après l’autre","La BSD ne conduit qu’un mode d’action à la fois"],a:0,e:"Il optimise les moyens de soutien et prend en compte leurs délais de mise en œuvre avant de concevoir un nouveau plan de soutien."}]},
{id:"sl_mco",grp:FX_GRP,title:"Maintien en condition opérationnelle des matériels",qtag:"MCO-T",
 but:"Connaître l’organisation de la maintenance, du contact au théâtre, et son fonctionnement, pour estimer la disponibilité des matériels de la brigade et les délais de remise en état.",
 sections:[
 {h:"Généralités",l:["Le MCO-T réunit les moyens, prestations et processus qui maintiennent un équipement apte à l’emploi, de sa mise en service à son retrait.","En opération, il maintient et restaure la capacité des matériels et préserve l’autonomie de la force ; son efficacité repose sur la planification, la modularité, la visibilité et la traçabilité de la ressource, et la résilience du personnel et des systèmes."]},
 {h:"Les trois niveaux de maintenance",l:["Maintenance de contact (groupement) : disponibilité technique maximale. Une équipe légère d’intervention (ELI) par sous-groupement, au TC1, trie les matériels réparables sur place ; la section de maintenance régimentaire (SMR), au TC2, répare au niveau technique d’intervention 1 en moins de 4 h en général ; son groupe de récupération-évacuation évacue vers le point de regroupement des matériels à réparer (PRMAR), en général colocalisé avec le TC2.","Maintenance de proximité (division) : autonomie maximale, en zone maintenance de la BSD. Une compagnie de maintenance mobilité soutient plusieurs groupements, avec une stabilité d’au moins 12 h et des interventions de niveau 2 de 8 h au plus ; chacune de ses sections de réparation soutient au moins un groupement.","Maintenance de théâtre : capacité à durer, en zone maintenance du GSIAT ; réparations lourdes, régénération, gestion des stocks de rechanges et de la réserve de matériels complets."]},
 {h:"Fonctionnement",l:["Le matériel en panne est diagnostiqué par l’ELI, puis évacué par le sous-groupement jusqu’au TC2, où il est trié : réparé par la SMR et rendu au plus vite, débordé vers la maintenance divisionnaire, ou irréparable et éventuellement détruit selon les directives.","La zone maintenance centralise les demandes de dépannage et d’évacuation ; si ses moyens sont saturés, elle demande l’appui du groupement d’appui à la mobilité des blindés. Elle récupère les matériels sur la position des TC2 ou au PRMAR, qui sert aussi de rendez-vous d’échange et de site de réparation temporaire.","Réparé, le matériel est rendu à sa formation, ou versé à la réserve s’il a déjà été remplacé ; au-delà des délais ou des moyens de la zone, il est transféré au niveau opératif."],go:["ap_mvt"]},
 {h:"Régimes de travail",l:["Le régime d’emploi est le nombre d’heures de réparation par équipe et par 24 h ; il s’adapte à l’intensité des combats et à l’attrition.","R1 : 10 h par jour, en continu. R2 : 14 h, moins de 8 jours. R3 : 18 h, moins de 72 h. R4 : 22 h, moins de 36 h.","Par équipe et par jour, en R1 : 1,25 intervention de 8 h (niveau 2) ou 2,5 de 4 h (niveau 1) ; en R4 : 2,75 ou 5,5."],go:["normes"]},
 {h:"Les approvisionnements",l:["Rechanges : gérés par les compagnies ou sections d’approvisionnement des zones maintenance ; les SMR et les sections de réparation ne détiennent qu’un volant de rechanges. Le niveau des stocks dépend des matériels déployés, de l’autonomie voulue et des conditions d’engagement.","Ressource locale possible (achat, impression 3D), avec restrictions : pas de pièces métalliques, ni d’organes de sécurité sans validation préalable.","Matériels complets : une réserve, en partie à la zone maintenance de la BSD, remplace les matériels non réparables à temps ; le groupement adresse sa demande au PC de la zone maintenance, et le matériel est en général livré au PRMAR. L’équipage du matériel remplacé y monte les équipements d’environnement (armement, optique, transmissions)."]}],
 vig:["Trier tôt : réparer au plus près ce qui peut l’être, déborder le reste.","Le PRMAR est un rendez-vous : le prévoir dans le dispositif, près du TC2.","Adapter le régime de travail à l’intensité, en sachant que les régimes élevés ne durent pas.","Un matériel de remplacement arrive nu : prévoir l’équipage pour monter les équipements d’environnement."],
 apply:[{t:"note",x:"Organise le soutien maintenance de ta manœuvre : pour chaque phase, l’emplacement des ELI, de la SMR et du PRMAR, le régime de travail et les priorités de réparation."},
  {t:"table",id:"slmco",l:"Soutien maintenance",cols:[{k:"ph",l:"Phase"},{k:"p",l:"PRMAR et SMR (emplacement)"},{k:"r",l:"Régime",o:["R1","R2","R3","R4"]},{k:"pr",l:"Priorités de réparation"},{k:"d",l:"Débordement et évacuation",s:1}]},
  {t:"doc",l:"Soutien maintenance"}],
 quiz:[
 {q:"Où se trouve l’équipe légère d’intervention (ELI) ?",o:["Au TC1 de chaque sous-groupement","Au TC2","En zone maintenance","Au PRMAR"],a:0,e:"Elle trie les matériels réparables immédiatement."},
 {q:"En combien de temps la SMR effectue-t-elle généralement ses réparations ?",o:["Moins de 4 h","Moins de 8 h","Moins de 12 h","Moins de 24 h"],a:0,e:"Réparations de niveau technique d’intervention 1."},
 {q:"Où le PRMAR est-il généralement colocalisé ?",o:["Avec un TC2","Avec la BSD","Avec le TC1","Avec le PC de la brigade"],a:0,e:"Il est placé sous la responsabilité de ce TC2."},
 {q:"Quel est le but de la maintenance de proximité ?",o:["Donner une autonomie maximale à la force soutenue","Donner une disponibilité technique maximale","Donner une capacité à durer","Régénérer le potentiel de la force"],a:0,e:"Contact : disponibilité ; théâtre : capacité à durer."},
 {q:"Quelle est la stabilité minimale d’une compagnie de maintenance mobilité ?",o:["12 h","4 h","24 h","120 h"],a:0,e:"Ses interventions de niveau 2 ne dépassent pas 8 h."},
 {q:"Vers qui la zone maintenance se tourne-t-elle quand ses moyens d’évacuation sont saturés ?",o:["Le groupement d’appui à la mobilité des blindés, via la division","Les TC2 du GTIA, par l’intermédiaire du B4 de la brigade","Le régiment du génie, via la cellule appui de la brigade","Le GSIAT, directement et sans passer par la division"],a:0,e:"Les porte-engins blindés appuient les évacuations."},
 {q:"Combien d’heures par jour une équipe travaille-t-elle en régime R3 ?",o:["18 h","10 h","14 h","22 h"],a:0,e:"Pendant moins de 72 h."},
 {q:"Combien de temps le régime R4 peut-il durer ?",o:["Moins de 36 h","Moins de 72 h","Moins de 8 jours","En continu"],a:0,e:"22 h de travail par jour."},
 {q:"Que ne permet pas l’impression 3D de rechanges ?",o:["Les pièces métalliques","Les pièces en plastique","Les petites pièces","Les pièces d’aménagement intérieur"],a:0,e:"Ni les organes de sécurité sans validation préalable."},
 {q:"Qui monte les équipements d’environnement sur un matériel de remplacement ?",o:["L’équipage du matériel remplacé, sous la responsabilité du TC2","La compagnie d’approvisionnement, sous la responsabilité de la BSD","La SMR seule, avant la livraison du matériel à l’unité","Le GSIAT, avant la mise en place du matériel sur le théâtre"],a:0,e:"Armement, optique, transmissions."}]},
{id:"sl_san",grp:FX_GRP,title:"Le soutien médical",qtag:"SAN",
 but:"Connaître les principes du soutien médical, les rôles de soins, les capacités et la régulation des blessés, pour planifier l’évacuation et le traitement des blessés de la brigade.",
 sections:[
 {h:"Principes",l:["Médicalisation à l’avant, avec le sauvetage au combat et la réanimation de sauvetage.","Réanimation et chirurgicalisation à l’avant, au plus tôt et au plus près du lieu de la blessure, dont la chirurgie de sauvetage.","Évacuation stratégique systématique et précoce : la France n’hospitalise pas longtemps sur le théâtre ; le blessé est traité définitivement sur le territoire national."]},
 {h:"Les quatre rôles",l:["Rôle 1 : soins de premier recours et prise en charge initiale, y compris réanimatoire ; le poste médical, en général dédié à un groupement tactique, se déploie en 1 h.","Rôle 2 : réanimation, chirurgie initiale et chirurgie de sauvetage. R2F (avancé) : léger, déployé ou désengagé en moins de 3 h, pour renforcer les TC2 ; 100 blessés triés et 8 interventions par jour, autonomie 48 h. R2B (de base) : modulaire, moins de 10 h, adapté à une BIA ; 100 blessés triés, 10 interventions par jour, 20 lits.","R2E (renforcé) : structure lourde, déployée en priorité en zone santé de la BSD ; 40 lits d’hospitalisation et 20 interventions par jour. Délai de déploiement : moins de 96 h ou 30 jours (valeur à confirmer).","Rôle 3 : hôpital médico-chirurgical au GSIAT (6 blocs, 150 lits, déploiement en 30 jours). Rôle 4 : traitement définitif, en général dans les hôpitaux des armées sur le territoire national."]},
 {h:"Catégories de blessés",l:["Catégorisation initiale, sur le lieu de la blessure puis au triage du rôle 2 : ALPHA, les plus graves, surtout hémorragiques, chirurgie de sauvetage dans les 2 h (20 % du flux) ; BRAVO, graves non hémorragiques, chirurgie dans les 6 h (40 %) ; CHARLIE, blessés légers (40 %).","Après le rôle 2, catégorisation ultérieure : légers (convalescence sur le théâtre) et lourds (hospitalisation longue)."],go:["p2e5"]},
 {h:"Capacités et chaîne médicale",l:["Évacuation par route (GRIFFON ou SERVAL sanitaires), par air (hélicoptère médicalisé, avion) ou par fer (train médicalisé). Unités spécialisées : unité médicale de transit (évacuation aérienne), unité médicale de décontamination, unité de distribution des produits de santé.","Chaque groupement dispose de capacités de rôle 1 : une équipe paramédicale mobile aux TC1, des équipes médicales mobiles et un poste médical mobile aux TC2.","Les BIA et la BSD arment une cellule de régulation des blessés dans leur PC : elle répartit les capacités, régule les flux et suit le ravitaillement médical ; à court de moyens, elle demande des évacuations à la cellule de la division, qui donne ses ordres à la zone santé.","La zone santé assure les opérations de niveau 2, gère les produits de santé et ravitaille les capacités médicales des groupements. Le GSIAT assure le rôle 3 et les évacuations stratégiques."],go:["sl_bsd"]}],
 vig:["ALPHA : chirurgie de sauvetage dans les 2 h : la place des rôles 2 en découle.","La cellule de régulation des blessés de la brigade répartit, régule et suit.","Toute structure santé déployée demande de l’eau : l’anticiper.","Prévoir l’itinéraire et les vecteurs d’évacuation dès la conception de la manœuvre."],
 apply:[{t:"note",x:"Planifie la chaîne d’évacuation de ta brigade : pour chaque échelon, l’emplacement, les capacités, le vecteur d’évacuation et le délai jusqu’au rôle 2 ; vérifie la règle des 2 h pour les blessés ALPHA."},
  {t:"table",id:"slsan",l:"Chaîne d’évacuation",cols:[{k:"e",l:"Échelon",o:["TC1 (équipe paramédicale)","TC2 (poste médical mobile)","R2F","R2B","Zone santé (R2E)"]},{k:"l",l:"Emplacement"},{k:"v",l:"Vecteur d’évacuation",o:["Route","Air","Fer"]},{k:"d",l:"Délai jusqu’au rôle 2"},{k:"o",l:"Observations",s:1}]},
  {t:"doc",l:"Chaîne d’évacuation"}],
 quiz:[
 {q:"Lequel n’est PAS un principe du soutien médical français ?",o:["L’hospitalisation prolongée sur le théâtre","La médicalisation à l’avant","La chirurgicalisation à l’avant","L’évacuation stratégique précoce"],a:0,e:"Le blessé est traité définitivement sur le territoire national."},
 {q:"Combien de rôles de soins distingue-t-on ?",o:["4","3","5","2"],a:0,e:"Du rôle 1 (premier recours) au rôle 4 (traitement définitif)."},
 {q:"Quel délai de chirurgie pour un blessé ALPHA ?",o:["Dans les 2 h","Dans les 6 h","Dans les 12 h","Dans les 24 h"],a:0,e:"20 % du flux journalier."},
 {q:"Quelle part du flux représentent les blessés BRAVO ?",o:["40 %","20 %","10 %","60 %"],a:0,e:"Chirurgie dans les 6 h."},
 {q:"En combien de temps un R2F se déploie-t-il ?",o:["Moins de 3 h","Moins de 1 h","Moins de 10 h","Moins de 24 h"],a:0,e:"Il est adapté au renforcement des TC2."},
 {q:"Quelle structure de rôle 2 est adaptée au soutien d’une BIA ?",o:["Le R2B","Le R2F","Le R2E","Le poste médical"],a:0,e:"Modulaire, déployé en moins de 10 h."},
 {q:"Quelle structure de rôle 2 offre la plus grande capacité d’hospitalisation ?",o:["Le R2E","Le R2F","Le R2B","Le poste médical mobile"],a:0,e:"40 lits d’hospitalisation (20 pour le R2B) ; il est déployé en priorité en zone santé de la BSD."},
 {q:"Où est déployé l’hôpital médico-chirurgical (rôle 3) ?",o:["Au GSIAT","En zone santé de la BSD","Au TC2","Sur le territoire national"],a:0,e:"Le rôle 4 est sur le territoire national."},
 {q:"Qui arme la cellule de régulation des blessés au niveau 3 ?",o:["Les BIA et la BSD","Les groupements tactiques","La zone santé seule","Le GSIAT"],a:0,e:"Elle répartit les capacités et régule les flux de blessés."},
 {q:"De quoi disposent les TC2 d’un groupement en matière médicale ?",o:["D’équipes médicales mobiles et d’un poste médical mobile","D’un R2F organique et d’une équipe chirurgicale avancée","D’une unité de transit et d’une équipe paramédicale mobile","D’un R2B et de moyens d’évacuation par voie aérienne"],a:0,e:"Les TC1 disposent d’une équipe paramédicale mobile."}]},
{id:"sl_sdc",grp:FX_GRP,title:"Soutien du combattant et personnes capturées",qtag:"SDC",
 but:"Connaître le soutien du combattant (vivres, eau, équipements, affaires mortuaires) et la gestion des personnes capturées, pour en prévoir les besoins et les ressources dans la manœuvre de la brigade.",
 sections:[
 {h:"Le soutien du combattant",l:["Il prolonge sur le théâtre le soutien de l’homme : satisfaction des besoins vitaux, mise à disposition et entretien des équipements de vie courante et de protection individuelle, ravitaillement en vivres (dont la production boulangère) et en eau, participation aux affaires mortuaires.","Il est mis en œuvre par le 14e régiment d’infanterie et de soutien logistique parachutiste, qui arme les zones soutien du combattant de la BSD et du GSIAT. Une compagnie de soutien du combattant soutient le volume d’une BIA.","Ravitaillement selon les mêmes procédures que les autres ressources ; par défaut, flux tirés et distribution."]},
 {h:"L’eau",l:["L’eau destinée à la consommation humaine (boisson, cuisine, hygiène) se distingue de l’eau technique (maintenance, travaux, entretien). L’eau embouteillée en fait partie, mais se contrôle.","Besoins : 10 L par homme et par jour en climat tempéré, 30 L en climat chaud ; environ 1 500 L par heure pour un centre de reconditionnement du personnel en décontamination ; en moyenne 100 L par homme pour une structure santé.","Toute structure santé rattachée à un TC2 ou à une structure temporaire impose d’anticiper son ravitaillement en eau."],go:["nr_dct"]},
 {h:"Les affaires mortuaires",l:["L’unité d’appartenance est l’acteur principal : elle récupère et évacue la dépouille vers la zone soutien du combattant ; les groupements doivent disposer des contenants prévus à cet effet.","Le décès est prononcé par l’unité santé du TC2 ou la zone santé ; le TC3 inventorie les effets et constitue le dossier ; la gendarmerie prévôtale appose les scellés ; la dépouille attend l’évacuation en conteneur frigorifique.","L’inhumation d’urgence relève d’une décision de la division ; elle est déconseillée en défensive. Elle se fait dans la dignité et le respect des croyances, avec marquage des corps et des sépultures."]},
 {h:"Le soutien de la décontamination",l:["La zone soutien du combattant fournit l’eau du chantier personnel en priorité, voire du chantier véhicules, et rééquipe les combattants en effets non décontaminables à la sortie du site (tenues, protections balistiques, petits matériels)."]},
 {h:"La gestion des personnes capturées",l:["En haute intensité, une division peut capturer de l’ordre de 200 prisonniers par jour.","Trois phases : la capture, par l’unité interarmes, avec l’interrogation initiale qui classe l’intérêt renseignement de A à D ; la rétention, du point de regroupement ou du centre de transit au centre de rétention, où se déroulent les interrogations complémentaires ; la libération dans la zone de capture, ou le transfert ; en cas de transfert vers le centre de rétention du corps d’armée ou de remise aux autorités locales, on parle de détention et non plus de rétention.","Question transverse : vivres et habillement, soins, transport vers l’arrière (la BSD n’en a pas les moyens), statut juridique conforme au droit des conflits armés, création des zones de regroupement et centres de transit par le génie ; protection (de l’ordre de 500 gardes en permanence pour 2 000 prisonniers, volume d’une division en 10 jours de haute intensité) ; exploitation du renseignement.","Le prisonnier de guerre relève d’un statut particulier : la nation qui capture est responsable de sa garde, sans transfert possible.","Dans la zone de la BIA, aucune unité n’est spécialisée : les moyens sont prélevés sur ses unités organiques."],go:["rn_b2"]}],
 vig:["Eau : 10 L par homme et par jour en climat tempéré, 30 L en climat chaud.","L’unité d’appartenance récupère et évacue ses morts.","Les personnes capturées consomment des moyens prélevés sur la brigade : les planifier.","Le renseignement issu des interrogations se traite au plus tôt."],
 apply:[{t:"note",x:"Prévois la gestion des personnes capturées dans ta zone : pour chaque phase, le lieu, l’unité responsable, les moyens prélevés et l’échelon qui reçoit."},
  {t:"table",id:"slpg",l:"Personnes capturées",cols:[{k:"ph",l:"Phase",o:["Capture et interrogation initiale","Point de regroupement","Centre de transit","Transfert vers l’arrière"]},{k:"l",l:"Lieu"},{k:"u",l:"Unité responsable"},{k:"m",l:"Moyens prélevés (garde, transport)"},{k:"o",l:"Observations",s:1}]},
  {t:"doc",l:"Personnes capturées"}],
 quiz:[
 {q:"Quel régiment met en œuvre le soutien du combattant ?",o:["Le 14e régiment d’infanterie et de soutien logistique parachutiste","Le 519e régiment du Train, spécialisé dans le transit maritime","Le régiment médical, au titre du soutien de l’homme","Le 2e régiment de dragons, au profit de la BSD et du GSIAT"],a:0,e:"Il arme les zones soutien du combattant de la BSD et du GSIAT."},
 {q:"Quel volume une compagnie de soutien du combattant soutient-elle ?",o:["Celui d’une BIA","Celui d’un GTIA","Celui d’une division","Celui d’un SGTIA"],a:0,e:"Elle peut aussi se spécialiser dans un domaine."},
 {q:"Quel est le besoin en eau de consommation par homme et par jour en climat chaud ?",o:["30 L","10 L","5 L","100 L"],a:0,e:"10 L en climat tempéré."},
 {q:"Quel est le besoin en eau d’un centre de reconditionnement du personnel en décontamination ?",o:["Environ 1 500 L par heure","Environ 150 L par heure","Environ 15 m³ par heure","Environ 100 L par jour"],a:0,e:"L’eau de décontamination du personnel doit être de l’eau de consommation."},
 {q:"Qui est l’acteur principal de la chaîne mortuaire ?",o:["L’unité d’appartenance du défunt","La zone soutien du combattant","La gendarmerie prévôtale","La zone santé"],a:0,e:"Elle récupère et évacue la dépouille."},
 {q:"Qui appose les scellés sur le contenant de la dépouille ?",o:["La gendarmerie prévôtale","Le TC3","La zone santé","Le commissaire du groupement"],a:0,e:"Le TC3 constitue le dossier d’accompagnement."},
 {q:"Qui décide d’une inhumation d’urgence ?",o:["La division","La brigade","Le chef du GTIA","La zone soutien du combattant"],a:0,e:"Elle est déconseillée en défensive."},
 {q:"Combien de prisonniers par jour une division peut-elle faire en haute intensité ?",o:["De l’ordre de 200","De l’ordre de 20","De l’ordre de 2 000","De l’ordre de 50"],a:0,e:"Environ 2 000 en 10 jours."},
 {q:"Combien de gardes faut-il en permanence pour un camp de 2 000 prisonniers ?",o:["De l’ordre de 500","De l’ordre de 100","De l’ordre de 1 000","De l’ordre de 50"],a:0,e:"Ordre de grandeur théorique."},
 {q:"Qui crée les zones de regroupement et centres de transit des personnes capturées ?",o:["Le génie","La BSD","La gendarmerie","Le service de santé"],a:0,e:"Au titre du soutien au stationnement."},
 {q:"Dans la zone de la BIA, qui gère les personnes capturées ?",o:["Des moyens prélevés sur les unités organiques de la brigade","Une unité spécialisée de prévôté, détachée par la division","La BSD, qui dispose d’une zone de regroupement dédiée","La division directement, par un détachement de transit"],a:0,e:"Aucune unité n’y est spécialisée."},
 {q:"Comment l’interrogation initiale classe-t-elle les personnes capturées ?",o:["De A à D, selon leur intérêt renseignement","De 1 à 4, selon leur grade et leur fonction","En amis, neutres et ennemis, selon leur statut","De A à D, selon leur état de santé"],a:0,e:"Les plus intéressantes rejoignent le centre d’interrogation."}]}
];
FX_MODS.push(...NR_MODS,...SL_MODS);
/* Encarts NRBC et soutien dans les étapes du cycle */
FX_ENC.push(
 ["p1e2",{h:"Contribution NRBC : risques industriels",l:["Recenser les sites industriels de la zone (chimie, hydrocarbures, nucléaire, laboratoires) : l’ennemi peut en faire des armes par destination. Le risque industriel et le risque biologique naturel se prennent toujours en compte."],go:["nr_men"]}],
 ["p1e3",{h:"Contribution NRBC : menace ennemie",l:["Évaluer les capacités NRBC ennemies et les effets qu’il recherche (interdire, freiner, détruire, neutraliser, leurrer, harceler) : PC et emprises logistiques sont des cibles privilégiées."],go:["nr_men"]}],
 ["p1e4",{h:"Contribution du soutien et de la défense NRBC : moyens amis",l:["Recenser l’autonomie (3 jours de combat aux groupements), l’emplacement des TC2 et l’élongation jusqu’à la BSD, les structures temporaires possibles (DAS, plots) et les moyens NRBC reçus."],go:["sl_div","sl_bsd","nr_def"]}],
 ["p2e2",{h:"Contribution du soutien : le volet logistique des MA",l:["Chaque MA comporte un volet logistique : des phases d’effort logistique encadrent l’effort tactique. Une décontamination approfondie met une unité hors de combat : la placer dans le temps de la manœuvre."],go:["sl_div","nr_dct"]}],
 ["p2e3",{h:"Contribution du soutien et de la défense NRBC : manœuvres fonctionnelles",l:["Concept de soutien par phase (flux, ravitaillement, structures, sûreté), chaîne d’évacuation des blessés, soutien maintenance, plan de décontamination et gestion des personnes capturées."],go:["sl_div","sl_san","nr_dct","sl_sdc"]}],
 ["p2e5",{h:"Contribution du soutien : délais en confrontation",l:["Vérifier les élongations (120 km au plus entre BSD et TC2), les délais des structures temporaires (plot en moins de 12 h, DAS pour environ 48 h), la règle des 2 h pour les blessés ALPHA et les 24 h au plus entre contamination et fin de décontamination."],go:["sl_bsd","sl_san","nr_dct"]}],
 ["or_opo",{h:"Contribution du soutien et de la défense NRBC : annexes R et U",l:["Le B4 rédige les paragraphes et l’annexe logistiques. Le plan de décontamination figure dans l’OPO (paragraphes et annexe NRBC) pour les mesures préparatoires ; un FRAGO le déclenche."],go:["sl_div","nr_dct"]}]
);
